/**
 * THE PARITY PROOF for a bot's members-only posts (`docs/security/private-repos.md` §23): every
 * `bot_post__*` vector in `forge-contracts/vectors/` (generated by
 * `tools/private-repos-vectors/bot_post.py`), run against `./bot-post` and `./doc`. forge-core
 * `private::bot_post::conformance` runs the same files with the same input and output shapes.
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'

import { PostKey, openBotPost, postKeyLetterFromTyped, postKeyLetterToTyped } from './bot-post'
import { bytesToHex, hexToBytes } from './bytes'
import { TooLargeError, maxMembersPlaintext, membersObjKey, openContent, openMembersWithKey, padded, V5, docAdIn, type OpenContext, type OpenResult, type PrivateDoc, type StoredPrivateDoc } from './doc'
import { IdSet, privateId } from './ids'
import { decodeKeyLetter, encodeKeyLetter } from './key-letter'
import { EpochKeys } from './keys'
import { sealBotPostWithNonce } from './testing'
import { MalformedError, encodeTlv, type DocFields, type PrivateDocType } from './tlv'

type Json = null | boolean | number | string | Json[] | { [k: string]: Json }
type Obj = { readonly [k: string]: Json }

interface Vector {
  readonly name: string
  readonly case: string
  readonly input: Obj
  readonly expected: Json
}

const VECTORS_DIR = resolve(process.cwd(), '..', 'forge-contracts', 'vectors')
const FILES = readdirSync(VECTORS_DIR)
  .filter((f) => f.startsWith('bot_post__') && f.endsWith('.json'))
  .sort()

const str = (j: Json | undefined): string => j as string
const num = (j: Json | undefined): number => j as number
const obj = (j: Json | undefined): Obj => j as Obj
const hex = (j: Json | undefined): Uint8Array => hexToBytes(str(j))
const optHex = (j: Json | undefined): Uint8Array | undefined => (j === undefined ? undefined : hex(j))

function toDoc(d: Obj): PrivateDoc {
  return {
    type: str(d.type) as PrivateDocType,
    vis: d.vis === undefined ? undefined : (str(d.vis) as 'public' | 'private'),
    ownerId: privateId(str(d.ownerId)),
    epoch: num(d.epoch),
    number: d.number === undefined ? undefined : num(d.number),
    targetId: optHex(d.targetId),
    patchId: optHex(d.patchId),
  }
}

function storedDoc(d: Obj): StoredPrivateDoc {
  return {
    ...toDoc(d),
    id: d.id === undefined ? undefined : privateId(str(d.id)),
    createdAtBlockHeight: d.createdAtBlockHeight === undefined ? undefined : num(d.createdAtBlockHeight),
    updatedAtBlockHeight: d.updatedAtBlockHeight === undefined ? undefined : num(d.updatedAtBlockHeight),
    enc: hex(d.enc),
  }
}

function toFields(f: Obj): DocFields {
  const out: { -readonly [K in keyof DocFields]: DocFields[K] } = {}
  for (const k of ['title', 'body', 'eventValue', 'refName'] as const) if (k in f) out[k] = str(f[k])
  return out
}

function fieldsJson(f: DocFields): Json {
  return Object.fromEntries(Object.entries(f).filter(([, v]) => v !== undefined)) as Json
}

function openedJson(r: OpenResult): Json {
  if (r.status === 'readable') return { status: 'readable', fields: fieldsJson(r.fields) }
  return r.status === 'unreadable' ? { status: 'unreadable', reason: r.reason } : { status: 'malformed' }
}

function postKey(i: Obj, epoch: number): Promise<PostKey> {
  return PostKey.of(hex(i.repoId), epoch, hex(i.bot), hex(i.w))
}

async function openContextOf(repoId: Uint8Array, c: Obj): Promise<OpenContext> {
  const keys = new Map<number, EpochKeys>()
  for (const [e, k] of Object.entries(obj(c.keys))) keys.set(Number(e), await EpochKeys.import(repoId, Number(e), hex(k)))
  const ids = (j: Json | undefined) => new IdSet(Array.isArray(j) ? j.map((m) => privateId(String(m))) : [])
  return {
    keys,
    anchors: new Map(
      Object.entries(obj(c.anchors)).map(([e, v]) => {
        const a = obj(v)
        return [Number(e), { id: privateId(str(a.id)), height: num(a.height), statedHeight: num(a.statedHeight ?? a.height) }]
      }),
    ),
    members: ids(c.members),
    burned: new Set(Array.isArray(c.burned) ? c.burned.map(Number) : []),
    bots: ids(c.bots),
  }
}

async function runPostKey(i: Obj): Promise<Json> {
  const keys = await EpochKeys.import(hex(i.repoId), num(i.epoch), hex(i.key))
  return { w: bytesToHex((await PostKey.derive(keys, hex(i.bot))).key()) }
}

async function runSeal(i: Obj): Promise<Json> {
  const doc = toDoc(obj(i.doc))
  const fields = toFields(obj(i.fields))
  // the key is the bot's, for epoch 0; a header under another epoch is the refusal under test
  const post = await postKey(i, 0)
  let sealed
  try {
    sealed = await sealBotPostWithNonce(post, doc, fields, hex(i.nonce))
  } catch (e) {
    if (e instanceof MalformedError) return { error: 'malformed' }
    if (e instanceof TooLargeError) return { error: 'tooLarge' }
    throw e
  }
  // the intermediates, recomputed from their definitions rather than read back from the seal
  expect(bytesToHex(sealed.ad)).toBe(bytesToHex(docAdIn(doc, hex(i.repoId), V5)))
  expect(bytesToHex(sealed.tlv)).toBe(bytesToHex(padded(doc.type, encodeTlv(fields), maxMembersPlaintext(doc.type))))
  expect(openedJson(await openBotPost(post, doc, sealed.enc))).toEqual({ status: 'readable', fields: fieldsJson(fields) })
  return {
    ad: bytesToHex(sealed.ad),
    kObj: bytesToHex(sealed.kObj),
    commit: bytesToHex(sealed.enc.subarray(13, 45)),
    tlv: bytesToHex(sealed.tlv),
    enc: bytesToHex(sealed.enc),
  }
}

async function runOpen(i: Obj): Promise<Json> {
  const repoId = hex(i.repoId)
  return openedJson(await openContent(storedDoc(obj(i.doc)), await openContextOf(repoId, obj(i.context))))
}

async function runOpenWithPostKey(i: Obj): Promise<Json> {
  const doc = storedDoc(obj(i.doc))
  return openedJson(await openBotPost(await postKey(i, num(i.epoch)), doc, doc.enc))
}

async function runObjKey(i: Obj): Promise<Json> {
  const repoId = hex(i.repoId)
  const doc = storedDoc(obj(i.doc))
  const keys = await EpochKeys.import(repoId, doc.epoch, hex(i.key))
  const k = await membersObjKey(keys, doc, doc.enc)
  if (k === null) return { kObj: null, opened: null }
  return { kObj: bytesToHex(k), opened: openedJson(await openMembersWithKey(repoId, doc, doc.enc, k)) }
}

function runLetter(i: Obj): Json {
  return { plaintext: bytesToHex(encodeKeyLetter(postKeyLetterToTyped({ epoch: num(i.epoch), key: hex(i.key) }))) }
}

function runLetterDecode(i: Obj): Json {
  const t = decodeKeyLetter(hex(i.plaintext))
  const l = t === null ? null : postKeyLetterFromTyped(t)
  return l === null ? null : { epoch: l.epoch, key: bytesToHex(l.key) }
}

describe('bot post conformance vectors', () => {
  it('finds them', () => {
    expect(FILES.length).toBeGreaterThanOrEqual(40)
  })
  for (const f of FILES) {
    const v = JSON.parse(readFileSync(resolve(VECTORS_DIR, f), 'utf8')) as Vector
    it(v.name, async () => {
      expect(v.case).toBe('bot_post')
      const i = v.input
      const run = {
        postKey: runPostKey,
        seal: runSeal,
        open: runOpen,
        openWithPostKey: runOpenWithPostKey,
        objKey: runObjKey,
        letter: runLetter,
        letterDecode: runLetterDecode,
      }[str(i.op)]
      if (run === undefined) throw new Error(`unknown op ${str(i.op)}`)
      expect(await run(i)).toEqual(v.expected)
    })
  }
})
